import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import { syncBuiltinESMExports } from "node:module";
import { tmpdir } from "node:os";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const RECORDER = "scripts/record-rule-suite-reads.mjs";
const RECORD_START = "/* BEGIN GENERATED RULE SUITE READS\n";
const RECORD_END = "\nEND GENERATED RULE SUITE READS */";
const TRACE_ROOT = "RMD_RULE_SUITE_TRACE_ROOT";
const TRACE_FILE = "RMD_RULE_SUITE_TRACE_FILE";

function recordBounds(source, path) {
  const marker = source.indexOf(RECORD_START);
  const end = source.lastIndexOf(RECORD_END);
  const start = marker + RECORD_START.length;
  if (marker < 0 || end < start) throw new Error(`Missing rule suite read record in ${path}`);
  return { start, end };
}

const recorderPath = fileURLToPath(import.meta.url);

function loadRecord() {
  const source = fs.readFileSync(recorderPath, "utf8");
  const { start, end } = recordBounds(source, recorderPath);
  return JSON.parse(source.slice(start, end));
}

export const RULE_SUITE_READS = loadRecord();

function readRoot(repoRoot, path) {
  if (path instanceof URL && path.protocol === "file:") path = fileURLToPath(path);
  if (Buffer.isBuffer(path)) path = path.toString();
  if (typeof path !== "string" || path.length === 0) return undefined;
  const local = relative(repoRoot, resolve(path));
  if (local === ".." || local.startsWith(`..${sep}`) || isAbsolute(local)) return undefined;
  return local.split(sep, 2).join("/") || ".";
}

function traceReads(repoRoot, traceFile) {
  const roots = new Set();
  function wrap(api, name) {
    const original = api[name];
    const traced = (path, ...args) => {
      const root = readRoot(repoRoot, path);
      // Loader realpath/stat probes of the checkout itself do not enumerate its contents.
      if (root !== undefined && (root !== "." || /^(readdir|opendir)/.test(name))) roots.add(root);
      return original.call(api, path, ...args);
    };
    api[name] = Object.assign(traced, original);
    if (original.native) wrap(api[name], "native");
  }
  for (const name of ["readFile", "readdir", "stat", "lstat", "open", "opendir", "access", "realpath", "readlink"]) {
    wrap(fs, name);
    wrap(fs, name + "Sync");
    wrap(fs.promises, name);
  }
  for (const name of ["exists", "existsSync", "createReadStream"]) wrap(fs, name);
  syncBuiltinESMExports();
  process.on("exit", () => fs.appendFileSync(traceFile, JSON.stringify([...roots]) + "\n"));
}

if (process.env[TRACE_ROOT] && process.env[TRACE_FILE]) {
  traceReads(process.env[TRACE_ROOT], process.env[TRACE_FILE]);
}

function suiteHash(repoRoot, suite) {
  return createHash("sha256").update(fs.readFileSync(join(repoRoot, suite))).digest("hex");
}

function writeRecord(path, rows) {
  const source = fs.readFileSync(path, "utf8");
  const { start, end } = recordBounds(source, path);
  const lines = Object.entries(rows).map(([suite, row]) => `  ${JSON.stringify(suite)}: ${JSON.stringify(row)}`);
  const json = `{\n${lines.join(",\n")}\n}`.replaceAll("*/", "*\\/");
  const contents = source.slice(0, start) + json + source.slice(end);
  const temp = fs.mkdtempSync(join(dirname(path), ".rule-suite-reads-"));
  try {
    const staged = join(temp, "record.mjs");
    fs.writeFileSync(staged, contents);
    fs.renameSync(staged, path);
  } finally {
    fs.rmSync(temp, { recursive: true });
  }
}

/** Refresh the embedded JSON snapshot with one serial traced run per suite. */
export function recordRuleSuiteReads(repoRoot, suites, suiteArgs) {
  repoRoot = resolve(repoRoot);
  const scratch = fs.mkdtempSync(join(tmpdir(), "rmd-rule-suite-reads-"));
  const rows = Object.create(null);
  let failed = 0;
  try {
    for (const [index, suite] of [...suites].sort().entries()) {
      const traceFile = join(scratch, String(index));
      const before = suiteHash(repoRoot, suite);
      const env = { ...process.env, [TRACE_ROOT]: repoRoot, [TRACE_FILE]: traceFile, NODE_V8_COVERAGE: "" };
      delete env.NODE_TEST_CONTEXT;
      console.log(`rule-checks: tracing reads for ${suite}`);
      const result = spawnSync(process.execPath, ["--require", recorderPath, ...suiteArgs(suite, repoRoot)], {
        cwd: repoRoot, env, stdio: "inherit",
      });
      const reports = fs.existsSync(traceFile) ? fs.readFileSync(traceFile, "utf8").trim().split("\n") : [];
      const observed = new Set(reports.flatMap((line) => JSON.parse(line)));
      // A recorded parent already intersects every diff its child would.
      const roots = [...observed].filter((path) => !path.includes("/") || !observed.has(path.split("/", 1)[0])).sort();
      const complete = result.status === 0 && roots.length > 0 && before === suiteHash(repoRoot, suite);
      rows[suite] = { sha256: before, roots, ...(complete ? {} : { incomplete: true }) };
      if (!complete) {
        failed++;
        console.error(`rule-checks: read trace incomplete for ${suite} (${result.error?.message ?? result.signal ?? result.status})`);
      }
    }
    writeRecord(join(repoRoot, RECORDER), rows);
    console.log(`rule-checks: recorded reads for ${suites.length} suites (${failed} incomplete)`);
    return failed === 0 ? 0 : 1;
  } finally {
    fs.rmSync(scratch, { recursive: true });
  }
}

const intersects = (a, b) => a === "." || a === b || a.startsWith(b + "/") || b.startsWith(a + "/");

export function selectRuleSuites(repoRoot, suites, changedPaths, record = RULE_SUITE_READS) {
  const wouldRun = [];
  const wouldSkip = [];
  for (const suite of suites) {
    const row = record[suite];
    let fresh = false;
    if (row && !row.incomplete && Array.isArray(row.roots) && row.roots.length > 0) {
      try {
        fresh = suiteHash(repoRoot, suite) === row.sha256;
      } catch (error) {
        if (error.code !== "ENOENT" && error.code !== "ENOTDIR") throw error;
      }
    }
    const keep = !fresh || row.roots.some((root) => changedPaths.some((path) => intersects(root, path)));
    (keep ? wouldRun : wouldSkip).push(suite);
  }
  return { wouldRun, wouldSkip };
}

export function ruleSuiteShadowLine(repoRoot, listSuites, base) {
  try {
    const diff = spawnSync("git", ["diff", "--name-only", "-z", "--no-renames", `${base}...HEAD`, "--"], {
      cwd: repoRoot, encoding: "utf8", maxBuffer: 8 * 1024 * 1024,
    });
    if (diff.status !== 0) throw new Error(diff.error?.message ?? diff.stderr.trim());
    const suites = listSuites();
    const { wouldSkip } = selectRuleSuites(repoRoot, suites, diff.stdout.split("\0").filter(Boolean));
    return `rule-checks: shadow would skip ${wouldSkip.length}/${suites.length} suites${wouldSkip.length ? `: ${wouldSkip.join(" ")}` : ""}`;
  } catch (error) {
    return `rule-checks: shadow unavailable: ${String(error?.message ?? error).replace(/\s+/g, " ")}`;
  }
}

